-- 11-15. VaultSign templates (completed, declined, expired, reminder, voided)
UPDATE "EmailTemplate" SET
  subject = CASE template_key
    WHEN 'vaultsign_completed' THEN 'Document signed successfully'
    WHEN 'vaultsign_declined' THEN 'Document signing declined'
    WHEN 'vaultsign_expired' THEN 'Document signing expired'
    WHEN 'vaultsign_reminder' THEN 'Reminder: Document needs your signature'
    WHEN 'vaultsign_voided' THEN 'Document signing voided'
  END,
  body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#F7F3E8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#263633;line-height:1.6;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#F7F3E8;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;box-shadow:0 1px 3px rgba(23,74,67,0.06);border:1px solid #E5DFCF;"><tr><td style="background-color:#174A43;padding:28px 32px;text-align:center;"><div style="font-family:Georgia,serif;font-size:24px;font-weight:700;color:#FFFFFF;">MyZipVault</div><div style="font-size:11px;font-weight:600;color:#D98F78;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;">VaultSign Update</div></td></tr><tr><td style="padding:36px;font-size:15px;color:#263633;"><p style="margin:0 0 16px;">Hello {{signer_name}},</p><p style="margin:0 0 16px;color:#5C6B66;">The document <strong style="color:#174A43;">{{document_title}}</strong> has a status update: <strong>{{status}}</strong>.</p><div style="text-align:center;margin:28px 0;"><a href="{{login_link}}" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">View Document</a></div></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
WHERE template_key IN ('vaultsign_completed', 'vaultsign_declined', 'vaultsign_expired', 'vaultsign_reminder', 'vaultsign_voided');

-- 16. welcome_client
UPDATE "EmailTemplate" SET
  subject = 'Welcome to MyZipVault',
  body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#F7F3E8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#263633;line-height:1.6;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#F7F3E8;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;box-shadow:0 1px 3px rgba(23,74,67,0.06);border:1px solid #E5DFCF;"><tr><td style="background-color:#174A43;padding:28px 32px;text-align:center;"><div style="font-family:Georgia,serif;font-size:24px;font-weight:700;color:#FFFFFF;">MyZipVault</div><div style="font-size:11px;font-weight:600;color:#D98F78;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;">Welcome</div></td></tr><tr><td style="padding:36px;font-size:15px;color:#263633;"><p style="margin:0 0 16px;">Hello {{client_name}},</p><p style="margin:0 0 16px;color:#5C6B66;">Welcome to MyZipVault — the professional network built exclusively for healthcare. Start by setting up your organization profile and posting your first job.</p><div style="text-align:center;margin:28px 0;"><a href="{{login_link}}" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">Get Started</a></div></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
WHERE template_key = 'welcome_client';

COMMIT;

-- Verification
SELECT
  template_key,
  CASE
    WHEN body LIKE '%#174A43%' AND body LIKE '%#F7F3E8%' AND body LIKE '%#D98F78%' THEN '✅ CRM Design'
    ELSE '❌ Old Design'
  END AS design_status
FROM "EmailTemplate"
ORDER BY template_key;
